363→            continue;
364→        }
365→        if !pattern.context.matches(context) {
366→            continue;
367→        }
368→        let re = Regex::new(pattern.regex).ok()?;
369→        if let Some(caps) = re.captures(error_output) {
370→            if let Some(fix) = (pattern.suggest)(&caps, context) {
371→                return Some(fix);
372→            }
373→        }
374→    }
375→    None
376→}
