100→/// Create an output callback that updates a spinner with live output lines.
101→///
102→/// The callback maintains a ring buffer of the last `max_lines` output lines
103→/// and updates the spinner message to show the base message plus those lines.
104→/// This gives users feedback that a command is actually making progress.
105→///
106→/// # Arguments
107→/// * `bar` - A cloned `ProgressBar` from the spinner
108→/// * `base_message` - The primary spinner message (e.g., "Running install_deps...")
109→/// * `indent` - Number of spaces to indent live output lines
110→/// * `max_lines` - Maximum number of live output lines to show (2-3 typical)
111→pub fn live_output_callback(
112→    bar: ProgressBar,
113→    base_message: String,
114→    indent: usize,
115→    max_lines: usize,
116→) -> crate::shell::OutputCallback {
117→    let buffer: Arc<Mutex<VecDeque<String>>> = Arc::new(Mutex::new(VecDeque::new()));
118→    let theme = BivvyTheme::new();
119→
120→    Box::new(move |line: OutputLine| {
121→        let text = match &line {
122→            OutputLine::Stdout(s) => s.trim_end().to_string(),
123→            OutputLine::Stderr(s) => s.trim_end().to_string(),
124→        };
125→
126→        // Skip empty lines
127→        if text.is_empty() {
128→            return;
129→        }
130→
131→        // Truncate long lines for display
132→        let display_text = if text.len() > 72 {
133→            format!("{}...", &text[..69])
134→        } else {
135→            text
136→        };
137→
138→        let mut buf = buffer.lock().unwrap();
139→        buf.push_back(display_text);
140→        while buf.len() > max_lines {
141→            buf.pop_front();
142→        }
143→
144→        // Build multi-line message: base message + indented output lines
145→        let prefix = " ".repeat(indent);
146→        let mut msg = base_message.clone();
147→        for line in buf.iter() {
148→            msg.push('\n');
149→            msg.push_str(&prefix);
150→            msg.push_str(&theme.dim.apply_to(format!("» {}", line)).to_string());
151→        }
152→
153→        bar.set_message(msg);
154→    })
155→}
